        PropertyMetadata(name='pattern', schema_name='pattern', schema_url='https://schema.org/pattern', ranges=('DefinedTerm', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=None, equivalent_properties=('http://unece.org/vocab#printDesignDescription',), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment="A pattern that something has, for example 'polka dot', 'striped', 'Canadian flag'. Values are typically expressed as text, although links to controlled value schemes are also supported.", label='pattern', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
        PropertyMetadata(name='positive_notes', schema_name='positiveNotes', schema_url='https://schema.org/positiveNotes', ranges=('ItemList', 'ListItem', 'Text', 'WebContent'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=None, equivalent_properties=(), subproperty_of=(), domains=('Product', 'Review'), external_domains=(), comment='Provides positive considerations regarding something, for example product highlights or (alongside [[negativeNotes]]) pro/con lists for reviews.\n\nIn the case of a [[Review]], the property describes the [[itemReviewed]] from the perspective of the review; in the case of a [[Product]], the product itself is being described.\n\nThe property values can be expressed either as unstructured text (repeated as necessary), or if ordered, as a list (in which case the most positive is at the beginning of the list).', label='positiveNotes', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2832',)),
