        PropertyMetadata(name='size', schema_name='size', schema_url='https://schema.org/size', ranges=('DefinedTerm', 'QuantitativeValue', 'SizeSpecification', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=None, equivalent_properties=('http://unece.org/vocab#sizeDescription',), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment="A standardized size of a product or creative work, specified either through a simple textual string (for example 'XL', '32Wx34L'), a  QuantitativeValue with a unitCode, or a comprehensive and structured [[SizeSpecification]]; in other cases, the [[width]], [[height]], [[depth]] and [[weight]] properties may be more applicable. ", label='size', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
